// DIV 3 LEVEL B (1000 rating) — typical: sort + greedy
// Problem: Given array, pair up elements to minimize the maximum pair sum
// Key insight: pair smallest with largest (sorted, pair indices 0 and n-1)
function minMaxPairSum(nums) {
    nums.sort((a,b)=>a-b);
    let maxSum = 0;
    const n = nums.length;
    for (let i = 0; i < n/2; i++) {
        maxSum = Math.max(maxSum, nums[i] + nums[n-1-i]);
    }
    return maxSum;
}
console.log(minMaxPairSum([3,5,2,3])); // 7 (pair [2,5] and [3,3])

// DIV 3 LEVEL C (1200 rating) — typical: prefix sum or two pointers
// Problem: Find max sum subarray of length exactly k
function maxSumSubarrayK(nums, k) {
    let windowSum = nums.slice(0,k).reduce((a,b)=>a+b,0);
    let maxSum = windowSum;
    for (let i = k; i < nums.length; i++) {
        windowSum += nums[i] - nums[i-k];
        maxSum = Math.max(maxSum, windowSum);
    }
    return maxSum;
}
console.log(maxSumSubarrayK([2,-1,2,-1,3], 3)); // 4 (2+-1+3)

// DIV 3 LEVEL D (1500 rating) — typical: non-obvious observation
// Problem: Given array, find minimum moves to make all elements equal
// where a move increments one element by 1
// Key insight: optimal target = median (not mean)
function minMovesToEqual(nums) {
    nums.sort((a,b)=>a-b);
    const median = nums[Math.floor(nums.length/2)];
    return nums.reduce((sum, x) => sum + Math.abs(x - median), 0);
}
console.log(minMovesToEqual([1,2,3])); // 2 (move 1->2 and 3->2)
console.log(minMovesToEqual([1,0,0,8,6])); // 14

