// CODEFORCES DIV 2 LEVEL C EXAMPLES

// DIV 2 C (1500 rating) — parity argument + greedy
// Problem: Given array, make all elements equal using +1 or -1 operations
// Minimum operations? Key insight: parity of total operations is fixed
// If sum of changes to reach target has different parity from array sum -> impossible
// Observation: target must have same parity as array average (or median)

// DIV 2 C (1400 rating) — non-trivial greedy
// Problem: Assign values to make array k-divisible with minimum changes
// Key insight: for each position mod k, count how many can become 0 with 1 move
function minChangesKDiv(arr, k) {
    // Count elements in each residue class mod k
    const residues = new Array(k).fill(0);
    for (const x of arr) residues[((x % k) + k) % k]++;
    // Elements already 0 mod k need no change
    // Others need exactly 1 change
    return arr.length - residues[0];
}
console.log(minChangesKDiv([1,2,3,4,5,6], 3)); // 4 (elements 1,2,4,5 need change)

// DIV 2 C (1600 rating) — amortised analysis observation
// Problem: Find minimum number of operations where each op doubles one element
// until all elements are equal
// Key insight: the answer equals log2(LCM / each element), sum of those
function minDoublings(nums) {
    function lcm(a, b) { return a * b / gcd(a, b); }
    function gcd(a, b) { return b === 0 ? a : gcd(b, a%b); }
    const L = nums.reduce(lcm);
    return nums.reduce((sum, x) => {
        let ops = 0, target = L;
        while (target > x) { target /= 2; ops++; }
        return sum + (target === x ? ops : Infinity);
    }, 0);
}
console.log(minDoublings([1, 2, 3, 4])); // Infinity (3 cannot become LCM=12 by doubling)
console.log(minDoublings([1, 2, 4, 8])); // 6 (1->2->4->8: 3 ops, 2->4->8: 2 ops, 4->8: 1 op)

