// PATTERN FREQUENCY TRACKER (across multiple contests)
const patternFrequency = {};
function addPattern(pattern, solved) {
    if (!patternFrequency[pattern]) patternFrequency[pattern] = {attempts:0, solves:0};
    patternFrequency[pattern].attempts++;
    if (solved) patternFrequency[pattern].solves++;
}

// After 10 contests, sort by solve rate to find weaknesses:
function getWeakPatterns(minAttempts = 3) {
    return Object.entries(patternFrequency)
        .filter(([_,v]) => v.attempts >= minAttempts)
        .map(([k,v]) => ({ pattern: k, solveRate: v.solves/v.attempts }))
        .sort((a,b) => a.solveRate - b.solveRate); // lowest first
}

